pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: a positive, practically-sized deposit
        amount = bound(amount, 1, 1e30);

        // owner of c is this test contract (msg.sender in setUp); fund it
        vm.deal(address(this), amount);
        // deposit via fallback: depositsCount increments, balance grows
        (bool depOk, ) = address(c).call{value: amount}("");
        require(depOk, "deposit failed");
        require(address(c).balance == amount, "setup balance mismatch");

        // owner calls withdrawAll; it must succeed and drain the balance
        c.withdrawAll();

        // general rule: after any owner withdrawAll on a funded contract,
        // the whole balance has been sent to the owner
        assertTrue(address(c).balance == 0);
    }
}

