pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 reentryAmount;

    // The owner (this test contract) re-enters C's payable fallback whenever
    // C transfers ether to it, redepositing a fuzzed amount.
    receive() external payable {
        (bool ok, ) = address(c).call{value: reentryAmount}("");
        require(ok, "reentry failed");
    }

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 reentry) public {
        amount = bound(amount, 0, 1e18);
        reentry = bound(reentry, 1, 1e18); // keep wide: any nonzero redeposit exposes the bug
        reentryAmount = reentry;

        // fund owner (this contract) and pre-deposit `amount` into C via its payable fallback
        vm.deal(address(this), amount + reentry);
        (bool okDep, ) = address(c).call{value: amount}("");
        require(okDep, "deposit failed");
        assertTrue(address(c).balance == amount, "pre-state");

        // drive c through withdrawAll as the owner
        c.withdrawAll();

        // Reference C performs exactly ONE withdrawal, so after the owner's
        // single re-entrant redeposit the balance is exactly reentry.
        // The mutant performs an EXTRA withdrawal, causing a SECOND redeposit:
        // balance becomes reentry + reentry != reentry.
        assertTrue(address(c).balance == reentry);
    }
}

